use super::*;
use std::collections::{BTreeMap,BTreeSet};
use semio_framework_os_kernel::sqlite_snapshot::{SqliteSnapshotPhase,validate_sqlite_database_schema,artifact::{FloatRow,Reconstruction}};
use semio_framework_artifact_flow_flow::{FlowNodeGui,FlowPreviewGui,FlowChannelRef,WidgetLayout,SynapseSpec,OrderedMap,OrderedSet,retained::{FlowOwner,FlowRetirement},neural::{ColdDictionaryBuilder,Neuron,Synapse}};
use semio_framework_artifact_playbook_playbook::{GenerationPlayState,FormGeneration};
fn count(table:&str)->usize{match table{"generation_document"=>4,"generation_host"=>5,"generation_widget"=>5,"generation_neuron_widget"=>4,"generation_widget_port"=>5,"generation_slider_widget"=>6,"generation_note_widget"|"generation_image_widget"|"generation_preview_widget"|"generation_action_widget"|"generation_export_widget"|"generation_gui_plain"|"generation_gui_note"|"generation_gui_image"=>2,"generation_variable_widget"|"generation_gui_variable"=>3,"generation_cluster_widget"|"generation_gui"=>4,"generation_widget_expanded"|"generation_gui_expanded"|"generation_array_element"=>4,"generation_host_synapse"|"generation_tree_synapse"|"generation_value"=>8,"generation_host_layout"|"generation_gui_slider"=>6,"generation_neural_dictionary"|"generation_tree"=>1,"generation_neural_entry"|"generation_preset"|"generation_answer"|"generation_object_member"=>5,"generation_neural_value"|"generation_tree_neuron"|"generation_gui_node"=>7,"generation_gui_preview"=>10,_=>0}}
fn ordered_table(t:&str)->bool{matches!(t,"generation_widget"|"generation_widget_port"|"generation_widget_expanded"|"generation_host_synapse"|"generation_host_layout"|"generation_neural_entry"|"generation_tree_neuron"|"generation_tree_synapse"|"generation_gui_node"|"generation_gui_preview"|"generation_gui_expanded"|"generation_preset"|"generation_answer"|"generation_array_element"|"generation_object_member")}
fn flag(r:FloatRow<'_>,i:usize)->Result<bool,String>{match r.integer(i)?{0=>Ok(false),1=>Ok(true),_=>Err("procedural boolean differs".into())}}
struct Reader<'a,'c,'p>{rows:BTreeMap<&'a str,BTreeMap<i64,FloatRow<'a>>>,groups:BTreeMap<(&'a str,i64),Vec<FloatRow<'a>>>,owned:Reconstruction<'c,'p>}
impl<'a,'c,'p> Reader<'a,'c,'p>{
 fn new(d:&'a SqliteDatabase,sql:&str,c:&'c mut SqliteSnapshotControl<'p>)->Result<Self,String>{validate_sqlite_database_schema(d,sql,c.limits()).map_err(|e|e.to_string())?;c.check_database(d,SqliteSnapshotPhase::ReconstructSnapshot)?;let mut rows=BTreeMap::new();let mut groups=BTreeMap::<(&str,i64),Vec<FloatRow<'_>>>::new();let mut units=0;for t in &d.tables{let mut table=BTreeMap::new();for r in &t.rows{if units%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,units,0)?;}units+=1;let row=FloatRow::new(r,columns(&t.name))?;if row.rowid<=0||row.integer(0)?!=row.rowid||row.values.len()!=count(&t.name)||table.insert(row.rowid,row).is_some(){return Err("procedural entity identity or column count differs".into())}if ordered_table(&t.name){groups.entry((&t.name,row.integer(1)?)).or_default().push(row);}}rows.insert(t.name.as_str(),table);}Ok(Self{rows,groups,owned:Reconstruction::new(c)?})}
 fn take(&mut self,t:&str,id:i64)->Result<FloatRow<'a>,String>{self.owned.scalar()?;self.rows.get_mut(t).ok_or("missing procedural table")?.remove(&id).ok_or_else(||format!("missing, repeated or cyclic procedural {t} ownership"))}
 fn order(&mut self,t:&'a str,parent:i64,index:usize)->Result<Vec<FloatRow<'a>>,String>{let mut rows=self.groups.remove(&(t,parent)).unwrap_or_default();self.owned.checkpoint()?;rows.sort_by_key(|r|r.integer(index).unwrap_or(-1));for(i,r)in rows.iter().enumerate(){self.owned.scalar()?;if r.integer(index)?!=ordinal(i)?{return Err("procedural ordinals must be contiguous".into())}self.rows.get_mut(t).ok_or("missing procedural table")?.remove(&r.rowid).ok_or("repeated procedural relationship identity")?;}self.owned.checkpoint()?;Ok(rows)}
 fn text(&mut self,r:FloatRow<'a>,i:usize)->Result<String,String>{self.owned.text(r.text(i)?)}
 fn optional(&mut self,r:FloatRow<'a>,i:usize)->Result<Option<String>,String>{r.optional_text(i)?.map(|s|self.owned.text(s)).transpose()}
 fn finish(mut self)->Result<(),String>{self.owned.checkpoint()?;if self.rows.values().any(|r|!r.is_empty()){return Err("unowned or wrong-kind procedural entity rows".into())}Ok(())}
}
fn shape(r:FloatRow<'_>,active:Option<usize>,end:usize)->Result<(),String>{for i in 2..end{if r.is_null(i)?!=(Some(i)!=active){return Err("procedural typed scalar presence differs".into())}}Ok(())}
struct DictFrame<'a>{entries:Vec<FloatRow<'a>>,next:usize,return_key:Option<String>,names:BTreeSet<&'a str>,builder:ColdDictionaryBuilder}
fn dictionary(r:&mut Reader<'_,'_,'_>,root:i64)->Result<Dictionary,String>{r.take("generation_neural_dictionary",root)?;let entries=r.order("generation_neural_entry",root,2)?;let mut stack=vec![DictFrame{entries,next:0,return_key:None,names:BTreeSet::new(),builder:ColdDictionaryBuilder::new()}];loop{r.owned.checkpoint()?;let next=stack.last_mut().and_then(|f|{let row=f.entries.get(f.next).copied();f.next+=usize::from(row.is_some());row});if let Some(entry)=next{if !stack.last_mut().unwrap().names.insert(entry.text(3)?){return Err("duplicate procedural dictionary key".into())}let key=r.text(entry,3)?;let v=r.take("generation_neural_value",entry.integer(4)?)?;let(kind,active)=match v.text(1)?{"null"=>("null",None),"boolean"=>("boolean",Some(2)),"integer"=>("integer",Some(3)),"decimal"=>("decimal",Some(4)),"string"=>("string",Some(5)),"dictionary"=>("dictionary",Some(6)),_=>return Err("unknown procedural neural value kind".into())};shape(v,active,7)?;if kind=="dictionary"{let id=v.integer(6)?;r.take("generation_neural_dictionary",id)?;let entries=r.order("generation_neural_entry",id,2)?;stack.push(DictFrame{entries,next:0,return_key:Some(key),names:BTreeSet::new(),builder:ColdDictionaryBuilder::new()});continue}let atom=match kind{"null"=>Atom::Null,"boolean"=>Atom::Boolean(flag(v,2)?),"integer"=>Atom::Integer(v.integer(3)?),"decimal"=>Atom::Decimal(v.real(4)?),"string"=>Atom::String(r.text(v,5)?),_=>unreachable!()};stack.last_mut().unwrap().builder.insert(key,NeuralValue::Atom(atom));}else{let f=stack.pop().unwrap();let value=f.builder.finish();if let Some(key)=f.return_key{stack.last_mut().unwrap().builder.insert(key,NeuralValue::Dictionary(value));}else{return Ok(value)}}}}
struct ValueOwner(Option<DslValue>);
impl ValueOwner{fn new(v:DslValue)->Self{Self(Some(v))}fn take(mut self)->DslValue{self.0.take().unwrap()}}
impl Drop for ValueOwner{fn drop(&mut self){let Some(root)=self.0.take()else{return};let mut pending=vec![root];while let Some(v)=pending.pop(){match v{DslValue::Array(values)=>pending.extend(values),DslValue::Object(values)=>pending.extend(values.into_iter().map(|(_,v)|v)),_=>{}}}}}
enum Values{Array(Vec<ValueOwner>),Object(Vec<(String,ValueOwner)>)}
struct ValueFrame<'a>{links:Vec<FloatRow<'a>>,next:usize,key:Option<String>,values:Values}
fn unsigned(text:&str)->Result<u64,String>{let value=text.parse::<u64>().map_err(|_|"procedural unsigned64 differs")?;if value.to_string()!=text{return Err("procedural unsigned64 must be canonical decimal".into())}Ok(value)}
fn value_scalar(r:&mut Reader<'_,'_,'_>,id:i64)->Result<(Option<ValueOwner>,Option<Values>),String>{let v=r.take("generation_value",id)?;let(kind,active)=match v.text(1)?{"null"=>("null",None),"boolean"=>("boolean",Some(2)),"unsigned"=>("unsigned",Some(3)),"integer"=>("integer",Some(4)),"float"=>("float",Some(5)),"string"=>("string",Some(6)),"bytes"=>("bytes",Some(7)),"array"=>("array",None),"object"=>("object",None),_=>return Err("unknown procedural answer kind".into())};shape(v,active,8)?;let value=match kind{"null"=>DslValue::Null,"boolean"=>DslValue::Bool(flag(v,2)?),"unsigned"=>DslValue::Number(Number::UInt(unsigned(v.text(3)?)?)),"integer"=>DslValue::Number(Number::Int(v.integer(4)?)),"float"=>DslValue::Number(Number::Float(v.real(5)?)),"string"=>DslValue::String(r.text(v,6)?),"bytes"=>DslValue::Bytes(r.owned.blob(v.blob(7)?)?),"array"=>return Ok((None,Some(Values::Array(Vec::new())))),"object"=>return Ok((None,Some(Values::Object(Vec::new())))),_=>unreachable!()};Ok((Some(ValueOwner::new(value)),None))}
fn answer(r:&mut Reader<'_,'_,'_>,root:i64)->Result<ValueOwner,String>{let(value,container)=value_scalar(r,root)?;if let Some(v)=value{return Ok(v)}let values=container.unwrap();let links=r.order(match values{Values::Array(_)=>"generation_array_element",Values::Object(_)=>"generation_object_member"},root,2)?;let mut stack=vec![ValueFrame{links,next:0,key:None,values}];loop{r.owned.checkpoint()?;let next=stack.last_mut().and_then(|f|{let row=f.links.get(f.next).copied();f.next+=usize::from(row.is_some());row});if let Some(link)=next{let object=matches!(stack.last().unwrap().values,Values::Object(_));let key=if object{Some(r.text(link,3)?)}else{None};let id=link.integer(if object{4}else{3})?;let(value,container)=value_scalar(r,id)?;if let Some(v)=value{match &mut stack.last_mut().unwrap().values{Values::Array(values)=>values.push(v),Values::Object(values)=>values.push((key.unwrap(),v))}}else{let values=container.unwrap();let links=r.order(match values{Values::Array(_)=>"generation_array_element",Values::Object(_)=>"generation_object_member"},id,2)?;stack.push(ValueFrame{links,next:0,key,values});}}else{let f=stack.pop().unwrap();let v=ValueOwner::new(match f.values{Values::Array(values)=>DslValue::Array(values.into_iter().map(ValueOwner::take).collect()),Values::Object(values)=>DslValue::Object(values.into_iter().map(|(k,v)|(k,v.take())).collect())});if let Some(parent)=stack.last_mut(){match &mut parent.values{Values::Array(values)=>values.push(v),Values::Object(values)=>values.push((f.key.unwrap(),v))}}else{return Ok(v)}}}}
struct TreeOwner(Option<Tree>);
impl TreeOwner{fn take(mut self)->Tree{self.0.take().unwrap()}}
impl Drop for TreeOwner{fn drop(&mut self){if let Some(t)=self.0.take(){FlowRetirement::from_owner(FlowOwner::Tree(t)).retire_cold();}}}
struct TreeFrame<'a>{neurons:Vec<FloatRow<'a>>,next:usize,tree:Option<Tree>,parent:Option<Neuron>}
impl Drop for TreeFrame<'_>{fn drop(&mut self){if let Some(t)=self.tree.take(){FlowRetirement::from_owner(FlowOwner::Tree(t)).retire_cold();}if let Some(n)=self.parent.take(){FlowRetirement::from_owner(FlowOwner::Neurons(vec![n])).retire_cold();}}}
fn tree_frame<'a>(r:&mut Reader<'a,'_,'_>,id:i64,parent:Option<Neuron>)->Result<TreeFrame<'a>,String>{let mut f=TreeFrame{neurons:Vec::new(),next:0,tree:Some(Tree::default()),parent};r.take("generation_tree",id)?;f.neurons=r.order("generation_tree_neuron",id,2)?;for s in r.order("generation_tree_synapse",id,2)?{f.tree.as_mut().unwrap().synapses.push(Synapse{id:r.text(s,3)?,from:r.text(s,4)?,to:r.text(s,5)?,from_port:r.text(s,6)?,to_port:r.text(s,7)?});}Ok(f)}
fn tree(r:&mut Reader<'_,'_,'_>,root:i64)->Result<TreeOwner,String>{let mut stack=vec![tree_frame(r,root,None)?];loop{r.owned.checkpoint()?;let next=stack.last_mut().and_then(|f|{let row=f.neurons.get(f.next).copied();f.next+=usize::from(row.is_some());row});if let Some(v)=next{let params=semio_framework_artifact_flow_flow::neural::cold::ColdOwner::new(dictionary(r,v.integer(5)?)?);let id=r.text(v,3)?;let kind=r.text(v,4)?;let subtree=if v.is_null(6)?{None}else{Some(v.integer(6)?)};let n=Neuron{id,kind,params:params.into_inner(),tree:None};if let Some(id)=subtree{stack.push(tree_frame(r,id,Some(n))?);}else{stack.last_mut().unwrap().tree.as_mut().unwrap().neurons.push(n);}}else{let mut f=stack.pop().unwrap();let tree=f.tree.take().unwrap();if let Some(mut parent)=f.parent.take(){parent.tree=Some(Box::new(tree));stack.last_mut().unwrap().tree.as_mut().unwrap().neurons.push(parent);}else{return Ok(TreeOwner(Some(tree)))}}}}
struct GuiOwner(Option<FlowUi>);
impl GuiOwner{fn take(mut self)->FlowUi{self.0.take().unwrap()}}
impl Drop for GuiOwner{fn drop(&mut self){if let Some(v)=self.0.take(){v.retire_cold();}}}
struct SetOwner(Option<OrderedSet>);
impl SetOwner{fn take(mut self)->OrderedSet{self.0.take().unwrap()}}
impl Drop for SetOwner{fn drop(&mut self){if let Some(v)=self.0.take(){FlowRetirement::from_owner(FlowOwner::Set(v)).retire_cold();}}}
fn expanded<'a>(r:&mut Reader<'a,'_,'_>,table:&'a str,owner:i64)->Result<SetOwner,String>{let mut v=SetOwner(Some(OrderedSet::new()));let mut names=BTreeSet::new();for row in r.order(table,owner,2)?{if !names.insert(row.text(3)?){return Err("duplicate procedural expanded path".into())}v.0.as_mut().unwrap().insert(r.text(row,3)?);}Ok(v)}
fn gui(r:&mut Reader<'_,'_,'_>,id:i64)->Result<GuiOwner,String>{let v=r.take("generation_gui",id)?;let mut gui=GuiOwner(Some(FlowUi{camera:CameraJson{x:v.real(1)?,y:v.real(2)?,zoom:v.real(3)?},nodes:OrderedMap::new(),previews:Vec::new()}));let mut names=BTreeSet::new();for n in r.order("generation_gui_node",id,2)?{if !names.insert(n.text(3)?){return Err("duplicate procedural gui node name".into())}let chrome=match n.text(6)?{"plain"=>{let v=r.take("generation_gui_plain",n.rowid)?;NodeChrome::Plain{preview:flag(v,1)?}},"slider"=>{let v=r.take("generation_gui_slider",n.rowid)?;NodeChrome::Slider{label:r.text(v,1)?,min:v.real(2)?,max:v.real(3)?,step:v.real(4)?,value:v.real(5)?}},"note"=>{let v=r.take("generation_gui_note",n.rowid)?;NodeChrome::Note{text:r.text(v,1)?}},"image"=>{let v=r.take("generation_gui_image",n.rowid)?;NodeChrome::Image{src:r.text(v,1)?}},"variable"=>{let v=r.take("generation_gui_variable",n.rowid)?;NodeChrome::Variable{name:r.text(v,1)?,schema:r.text(v,2)?}},_=>return Err("unknown procedural gui chrome kind".into())};let name=r.text(n,3)?;gui.0.as_mut().unwrap().nodes.insert(name,FlowNodeGui{layout:WidgetLayout{x:n.real(4)?,y:n.real(5)?},chrome});}
 for v in r.order("generation_gui_preview",id,2)?{if v.is_null(4)?!=v.is_null(5)?||v.is_null(8)?!=v.is_null(9)?{return Err("procedural optional preview presence differs".into())}let source=if v.is_null(4)?{None}else{Some(FlowChannelRef{neuron:r.text(v,4)?,channel:r.text(v,5)?})};let layout=if v.is_null(8)?{None}else{Some(WidgetLayout{x:v.real(8)?,y:v.real(9)?})};let preview=semio_framework_artifact_flow_flow::neural::cold::ColdOwner::new(dictionary(r,v.integer(7)?)?);let expanded=expanded(r,"generation_gui_expanded",v.rowid)?;let id=r.text(v,3)?;let mode=r.text(v,6)?;gui.0.as_mut().unwrap().previews.push(FlowPreviewGui{id,source,mode,preview:preview.into_inner(),expanded:expanded.take(),layout});}Ok(gui)}
struct HostOwner(Option<FlowHostSnapshot>);
impl HostOwner{fn take(mut self)->FlowHostSnapshot{self.0.take().unwrap()}}
impl Drop for HostOwner{fn drop(&mut self){if let Some(v)=self.0.take(){v.retire_cold();}}}
struct GenerationOwner(Option<GenerationPlayState>);
impl GenerationOwner{fn take(mut self)->GenerationPlayRoot{self.0.take().unwrap().into()}}
impl Drop for GenerationOwner{fn drop(&mut self){if let Some(v)=self.0.take(){GenerationPlayRoot::from(v).retire_cold();}}}
fn ports(r:&mut Reader<'_,'_,'_>,owner:i64)->Result<(Vec<String>,Vec<String>),String>{let rows=r.groups.remove(&("generation_widget_port",owner)).unwrap_or_default();let(mut input,mut output)=(Vec::new(),Vec::new());for row in rows{r.take("generation_widget_port",row.rowid)?;match row.text(2)?{"input"=>input.push(row),"output"=>output.push(row),_=>return Err("procedural port direction differs".into())}}let mut values=[Vec::new(),Vec::new()];for(i,rows)in[input,output].iter_mut().enumerate(){r.owned.checkpoint()?;rows.sort_by_key(|r|r.integer(3).unwrap_or(-1));for(j,row)in rows.iter().enumerate(){if row.integer(3)?!=ordinal(j)?{return Err("procedural port ordinals must be contiguous".into())}values[i].push(r.text(*row,4)?);}}let[input,output]=values;Ok((input,output))}
/// 📥️ Restores the actual two owned domain fields after complete structural consumption.
pub fn reconstruct(d:&SqliteDatabase,sql:&str,c:&mut SqliteSnapshotControl<'_>)->Result<(FlowHostSnapshot,GenerationPlayRoot),String>{let mut r=Reader::new(d,sql,c)?;let document=r.take("generation_document",1)?;if document.integer(1)?!=1{return Err("procedural host root must be one".into())}let v=r.take("generation_host",1)?;let schema=r.text(v,1)?;let mut host=HostOwner(Some(FlowHostSnapshot{schema,camera:CameraJson{x:v.real(2)?,y:v.real(3)?,zoom:v.real(4)?},widgets:Vec::new(),synapses:Vec::new(),layout:OrderedMap::new()}));
 for w in r.order("generation_widget",1,2)?{let id=r.text(w,3)?;let widget=match w.text(4)?{"neuron"=>{let v=r.take("generation_neuron_widget",w.rowid)?;let params=semio_framework_artifact_flow_flow::neural::cold::ColdOwner::new(dictionary(&mut r,v.integer(2)?)?);let(input_ports,output_ports)=ports(&mut r,w.rowid)?;let neuron_kind=r.text(v,1)?;let preview=flag(v,3)?;Widget::Neuron{id,neuron_kind,params:params.into_inner(),input_ports,output_ports,preview}},"input_slider"=>{let v=r.take("generation_slider_widget",w.rowid)?;Widget::InputSlider{id,label:r.text(v,1)?,value:v.real(2)?,min:v.real(3)?,max:v.real(4)?,step:v.real(5)?}},"input_note"=>{let v=r.take("generation_note_widget",w.rowid)?;Widget::InputNote{id,text:r.text(v,1)?}},"input_image"=>{let v=r.take("generation_image_widget",w.rowid)?;Widget::InputImage{id,src:r.text(v,1)?}},"variable"=>{let v=r.take("generation_variable_widget",w.rowid)?;Widget::Variable{id,name:r.text(v,1)?,schema:r.text(v,2)?}},"output_preview"=>{let v=r.take("generation_preview_widget",w.rowid)?;let preview=semio_framework_artifact_flow_flow::neural::cold::ColdOwner::new(dictionary(&mut r,v.integer(1)?)?);let expanded=expanded(&mut r,"generation_widget_expanded",w.rowid)?;Widget::OutputPreview{id,preview:preview.into_inner(),expanded:expanded.take()}},"output_action"=>{let v=r.take("generation_action_widget",w.rowid)?;Widget::OutputAction{id,action:r.text(v,1)?}},"output_export"=>{let v=r.take("generation_export_widget",w.rowid)?;Widget::OutputExport{id,format:r.text(v,1)?}},"cluster"=>{let v=r.take("generation_cluster_widget",w.rowid)?;let tree=tree(&mut r,v.integer(2)?)?;let gui=gui(&mut r,v.integer(3)?)?;let name=r.text(v,1)?;Widget::Cluster{id,name,tree:tree.take(),flow:gui.take()}},_=>return Err("unknown procedural widget kind".into())};host.0.as_mut().unwrap().widgets.push(widget);}
 for v in r.order("generation_host_synapse",1,2)?{host.0.as_mut().unwrap().synapses.push(SynapseSpec{id:r.text(v,3)?,from:r.text(v,4)?,to:r.text(v,5)?,from_port:r.text(v,6)?,to_port:r.text(v,7)?});}let mut names=BTreeSet::new();for v in r.order("generation_host_layout",1,2)?{if !names.insert(v.text(3)?){return Err("duplicate procedural host layout key".into())}host.0.as_mut().unwrap().layout.insert(r.text(v,3)?,WidgetLayout{x:v.real(4)?,y:v.real(5)?});}
 let selected_generation_id=r.optional(document,2)?;let preview_text=r.optional(document,3)?;let mut generation=GenerationOwner(Some(GenerationPlayState{generations:Vec::new(),selected_generation_id,preview_text}));for g in r.order("generation_preset",1,2)?{let id=r.text(g,3)?;let name=r.text(g,4)?;generation.0.as_mut().unwrap().generations.push(FormGeneration{id,name,values:Default::default()});let mut keys=BTreeSet::new();for v in r.order("generation_answer",g.rowid,2)?{if !keys.insert(v.text(3)?){return Err("duplicate procedural generation answer key".into())}let key=r.text(v,3)?;let value=answer(&mut r,v.integer(4)?)?;generation.0.as_mut().unwrap().generations.last_mut().unwrap().values.insert(key,value.take());}}r.finish()?;Ok((host.take(),generation.take()))}
